namespace Fanex.Tarus.Customer.Controller
{
    using System.Collections.Generic;
    using System.Diagnostics.CodeAnalysis;
    using System.Linq;
    using System.Web.Mvc;
    using Fanex.Tarus.Customer.Business.ViewPT;
    using Fanex.Tarus.Customer.Criteria.ViewPT;
    using Fanex.Tarus.Web.Controllers;
    using Infrastructure.Constants;
    using Sunplus.Accounting.Business.Security;
    using Sunplus.Accounting.Core.Common;

    [SuppressMessage("Microsoft.StyleCop.CSharp.DocumentationRules", 
        "SA1600:ElementsMustBeDocumented", 
        Justification = "Reviewed. Suppression is OK here.")]
    public class ViewPTController : BaseController
    {
        private readonly IViewPTService _serviceManager;

        public ViewPTController()
            : this(null)
        {
        }

        public ViewPTController(IViewPTService serviceManager)
        {
            this._serviceManager = serviceManager ?? new ViewPTService();
        }

        [HttpPost]
        public JsonResult GetPTSetting(GetPTSettingCriteria criteria)
        {
            var result = this._serviceManager.GetPTSetting(criteria);

            var jsonResult = Json(result);
            jsonResult.JsonRequestBehavior = JsonRequestBehavior.AllowGet;
            return jsonResult;
        }

        [HttpPost]
        public JsonResult CheckDepositCustomer(string username)
        {
            var isDepositCustomer = this._serviceManager.CheckDepositCustomer(username);

            return Json(isDepositCustomer, JsonRequestBehavior.AllowGet);
        }

        public ActionResult GetBettypesReference()
        {
            if (!Permissions.HasPermission(Enumerations.Functions.AccessSpecialSites))
            {
                IList<int> exclusiveRefSportIds = new List<int>(8);

                for (int i = Sports.NG2Start; i <= Sports.NG2End; i++)
                {
                    exclusiveRefSportIds.Add(i);
                }

                ViewData["ExclusiveRefSportIds"] = exclusiveRefSportIds.ToArray();
            }

            return View("~/Views/PTInformation/Index.cshtml");
        }
    }
}
